import { useRef, useState } from "react";
import api from "../api";

interface User {
  _id: string;
  firstName: string;
  lastName: string;
  role: string;
}

interface Props {
  users: User[];
  onClose: () => void;
  onCreated: () => void;
}

type Status = "Open" | "In Progress" | "Closed";
type Priority = "Low" | "Medium" | "High";
type Category = "Billing" | "Technical" | "General";

const CreateTicketForm: React.FC<Props> = ({ onClose, onCreated }) => {
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [status, setStatus] = useState<Status>("Open");
  const [priority, setPriority] = useState<Priority>("Medium");
  const [category, setCategory] = useState<Category>("General");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  // ✅ instant lock (prevents double submit even before state updates)
  const submittingRef = useRef(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // ✅ hard stop for double clicks / enter spam
    if (submittingRef.current) return;
    submittingRef.current = true;

    setError("");

    if (!title.trim()) {
      setError("Title is required");
      submittingRef.current = false;
      return;
    }

    setLoading(true);

    try {
      await api.post("/tickets", {
        title: title.trim(),
        description: description.trim(),
        category,
        // status & priority intentionally omitted (server defaults)
      });

      onCreated();
      onClose();
    } catch (err: any) {
      const msg =
        err?.response?.data?.message ||
        err?.response?.data?.error ||
        "Failed to create ticket";
      setError(msg);
    } finally {
      setLoading(false);
      submittingRef.current = false;
    }
  };

  return (
    <div>
      <h3>Create Ticket</h3>

      <form onSubmit={handleSubmit}>
        <input
          placeholder="Title"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          required
          disabled={loading}
        />
        <br />

        <textarea
          placeholder="Description"
          value={description}
          onChange={(e) => setDescription(e.target.value)}
          rows={3}
          style={{ width: "200px" }}
          disabled={loading}
        />
        <br />

        <label>Status: </label>
        <select
          value={status}
          onChange={(e) => setStatus(e.target.value as Status)}
          disabled
        >
          <option value="Open">Open</option>
          <option value="In Progress">In Progress</option>
          <option value="Closed">Closed</option>
        </select>
        <br />

        <label>Priority: </label>
        <select
          value={priority}
          onChange={(e) => setPriority(e.target.value as Priority)}
          disabled
        >
          <option value="Low">Low</option>
          <option value="Medium">Medium</option>
          <option value="High">High</option>
        </select>
        <br />

        <label>Category: </label>
        <select
          value={category}
          onChange={(e) => setCategory(e.target.value as Category)}
          disabled={loading}
        >
          <option value="Billing">Billing</option>
          <option value="Technical">Technical</option>
          <option value="General">General</option>
        </select>
        <br />

        <button type="submit" disabled={loading}>
          {loading ? "Creating..." : "Create"}
        </button>

        <button
          type="button"
          onClick={onClose}
          disabled={loading}
          style={{ marginLeft: "10px" }}
        >
          Cancel
        </button>
      </form>

      {error && <p style={{ color: "red" }}>{error}</p>}
    </div>
  );
};

export default CreateTicketForm;
